-- Synthetic forward-test fixture for research.forward_test (R10). Not real trades.
-- Column names follow fx_ai_engine/database/db.py; only the columns the evaluator reads are created.
-- Window used by the tests: start 2027-01-04T00:00:00+00:00 (Monday), as-of 2027-02-15T00:00:00+00:00 (30 weekdays).
-- 30 in-window core_srs/mt5 closed trades: 13 wins at +2.0R, 17 losses at -1.0R, risk $32 per 1R on $1,000.
CREATE TABLE trades (id INTEGER PRIMARY KEY AUTOINCREMENT, trade_id TEXT UNIQUE, evidence_stream TEXT, policy_mode TEXT,
  execution_mode TEXT, account_scope TEXT, symbol TEXT, direction TEXT, status TEXT, reason_code TEXT, profit_loss REAL,
  r_multiple REAL, open_time TEXT, close_time TEXT);
CREATE TABLE account_metrics (id INTEGER PRIMARY KEY AUTOINCREMENT, timestamp TEXT, evidence_stream TEXT, policy_mode TEXT,
  execution_mode TEXT, account_scope TEXT, balance REAL, equity REAL, is_trading_halted INTEGER);
CREATE TABLE execution_feedback_conflicts (id INTEGER PRIMARY KEY AUTOINCREMENT, evidence_stream TEXT, account_scope TEXT,
  dedupe_key TEXT, trade_id TEXT, reason TEXT, payload_json TEXT, created_at TEXT, resolved_at TEXT);
-- Excluded rows: before the start, other policy mode, still open, rejected.
